command:
set +e
set -uo pipefail
export PATH=/opt/conda/bin:$PATH
export TMPDIR=/tmp HOME=/tmp
cd /tmp

# spawn runs task commands under bash -e; `set -uo pipefail` does not clear it (spawn#707).
#
# THE COMPARISON IS IN AWK, NOT PYTHON. This aarchbio image wraps a single C binary and has
# NO python3 at all -- the first version of this task reached the comparison and died on
# `python3: command not found` after plink2 had already produced every output. A bioconda
# single-tool image is not a conda env image; do not assume an interpreter is present.

echo "== the fileset must be the exact bytes PLINK 1.9 analysed =="
sha256sum -c data.sha256 || { echo "FAIL: the fileset differs from what PLINK 1.9 used"; exit 1; }
printf 'same_bytes\tdata.{bed,bim,fam} match PLINK 1.9 staged sha256\n'

plink2 --version | head -1

echo "== PLINK 2: the same three computations =="
plink2 --bfile data --freq counts --out p2 > /tmp/freq2.log 2>&1 || { cat /tmp/freq2.log; exit 1; }
plink2 --bfile data --missing     --out p2 > /tmp/miss2.log 2>&1 || { cat /tmp/miss2.log; exit 1; }
plink2 --bfile data --hardy       --out p2 > /tmp/hwe2.log  2>&1 || { cat /tmp/hwe2.log;  exit 1; }
ls -l p2.acount p2.vmiss p2.hardy | awk '{print "out\t"$9"\t"$5}'
head -1 p2.acount | sed 's/^/  acount header: /'
head -1 p2.vmiss  | sed 's/^/  vmiss header:  /'
head -1 p2.hardy  | sed 's/^/  hardy header:  /'

# ---------------------------------------------------------------- 1. allele counts, exact
# A1 in PLINK 1.9 is the MINOR allele; PLINK 2 reports the ALT allele. Comparing "A1 count"
# to "ALT count" compares two different quantities and would disagree on roughly half the
# variants -- a method difference wearing the clothes of a bug. min(count, total-count) is the
# minor count under EITHER convention, and it is an integer, so this is exact equality.
awk '
  NR==FNR { m19[$1]=$2+0; t19[$1]=$3+0; next }
  FNR==1 {
    for (i=1; i<=NF; i++) { h=$i; sub(/^#/,"",h); col[h]=i }
    if (!("ID" in col) || !("ALT_CTS" in col) || !("OBS_CT" in col)) {
      printf "FAIL: p2.acount header lacks ID/ALT_CTS/OBS_CT\n"; exit 2 }
    next
  }
  {
    id=$(col["ID"]); alt=$(col["ALT_CTS"])+0; obs=$(col["OBS_CT"])+0
    n++
    if (!(id in m19)) { printf "FAIL: %s absent from PLINK 1.9 output\n", id; exit 2 }
    m2 = (alt < obs-alt ? alt : obs-alt)
    if (t19[id] != obs) { bt++; if (ex<3) { printf "example\ttotal %s %d vs %d\n", id, t19[id], obs; ex++ } }
    if (m19[id] != m2)  { bm++; if (ex<3) { printf "example\tminor %s %d vs %d\n", id, m19[id], m2;  ex++ } }
  }
  END{
    printf "variants_compared\t%d\n", n+0
    printf "total_allele_mismatches\t%d\n", bt+0
    printf "minor_allele_count_mismatches\t%d\n", bm+0
  }' p19.minor.tsv p2.acount | tee counts.tsv
test "${PIPESTATUS[0]}" = "0" || { echo "FAIL: allele-count comparison errored"; exit 1; }

NC=$(awk -F'\t' '$1=="variants_compared"{print $2}' counts.tsv)
BT=$(awk -F'\t' '$1=="total_allele_mismatches"{print $2}' counts.tsv)
BM=$(awk -F'\t' '$1=="minor_allele_count_mismatches"{print $2}' counts.tsv)
test "$NC" -gt 900 || { echo "FAIL: only $NC variants compared, expected ~1000"; exit 1; }
test "$BT" = "0" || { echo "FAIL: $BT total-allele mismatches"; exit 1; }
test "$BM" = "0" || { echo "FAIL: $BM minor-allele-count mismatches"; exit 1; }
printf 'identity_counts\tminor-allele counts and total observations identical, exactly\n'

# ---------------------------------------------------------------- 2. missing counts, exact
awk '
  NR==FNR { n19[$1]=$2+0; next }
  FNR==1 { for (i=1;i<=NF;i++){h=$i; sub(/^#/,"",h); col[h]=i}
           if (!("ID" in col) || !("MISSING_CT" in col)) { printf "FAIL: p2.vmiss header\n"; exit 2 } next }
  { id=$(col["ID"]); mc=$(col["MISSING_CT"])+0
    if (id in n19) { n++; if (n19[id] != mc) { b++; if (ex<3) { printf "example\tmiss %s %d vs %d\n", id, n19[id], mc; ex++ } } } }
  END{ printf "missing_compared\t%d\nmissing_ct_mismatches\t%d\n", n+0, b+0 }' p19.miss.tsv p2.vmiss | tee miss.tsv
test "${PIPESTATUS[0]}" = "0" || { echo "FAIL: missingness comparison errored"; exit 1; }
BMI=$(awk -F'\t' '$1=="missing_ct_mismatches"{print $2}' miss.tsv)
test "$BMI" = "0" || { echo "FAIL: $BMI missing-count mismatches"; exit 1; }
printf 'identity_missing\tper-variant missing counts identical, exactly\n'

# ------------------------------------------- 3. HWE p-values: same test, printed precision
# Both implement the same exact test, so any residual is the ~4 significant figures each tool
# PRINTS, not a numerical disagreement. The bound is therefore justified by the output format,
# which is stated rather than tuned.
awk '
  NR==FNR { p19[$1]=$2; next }
  FNR==1 { for (i=1;i<=NF;i++){h=$i; sub(/^#/,"",h); col[h]=i}
           pc = ("P" in col) ? col["P"] : (("MIDP" in col) ? col["MIDP"] : 0)
           if (!("ID" in col) || pc==0) { printf "hwe\tno usable P column -- reported, not asserted\n"; skip=1 }
           next }
  skip { next }
  { id=$(col["ID"]); if (id in p19) { a=p19[id]+0; b=$(pc)+0; d=a-b; if (d<0) d=-d; n++; if (d>w) w=d } }
  END{ if (!skip) { printf "hwe_compared\t%d\nhwe_max_abs_diff\t%.3e\n", n+0, w+0 } }' p19.hwe.tsv p2.hardy | tee hwe.tsv
HW=$(awk -F'\t' '$1=="hwe_max_abs_diff"{print $2}' hwe.tsv)
if [ -n "$HW" ]; then
  awk -v w="$HW" 'BEGIN{ if (w+0 > 1e-4) { printf "FAIL: HWE p-values differ by %s, more than printed precision explains\n", w; exit 1 } }' || exit 1
  printf 'agreement_hwe\tHWE p-values agree to printed precision\n'
fi

{ printf 'observable\tvalue\n'; cat counts.tsv miss.tsv hwe.tsv; } > score.tsv
# compare.log is a DECLARED OUTPUT, so it must be written. The python version produced it via
# `tee`; when the comparison was rewritten in awk the tee went away but the output declaration
# stayed, and spawn correctly failed the task on a declared-but-missing file even though the
# science had already passed with rc=0. Build it explicitly rather than dropping the output.
cat counts.tsv miss.tsv hwe.tsv > compare.log

# WHY NO ASSOCIATION COMPARISON. PLINK 1.9's --assoc is an allelic chi-square; PLINK 2 removed
# it in favour of --glm, a regression. DIFFERENT TESTS, so comparing their statistics would
# measure the method change rather than the two implementations. Stated, not forced.
printf 'note\t--assoc (1.9) and --glm (2.0) are different tests; no association comparison made\n'
cp score.tsv plink2-diag.txt
uname -m | awk '{print "arch\t"$1}'
echo "PLINK2 CROSSCHECK OK"
